INSERT INTO item(user_id, service_id)
SELECT #{item.userId}, #{item.serviceId}
WHERE NOT EXISTS (
    SELECT 1 FROM item i
    WHERE i.user_id = #{item.userId}
      AND i.service_id = #{item.serviceId}
      AND i.manage_status IN (#{pendingCode}, #{approvedCode})
)

INSERT INTO item(user_id, service_id, consultant_id, slot_id, slot_date, start_time, end_time)
SELECT #{item.userId}, #{item.serviceId}, #{item.consultantId}, #{item.slotId},
       #{item.slotDate}, #{item.startTime}, #{item.endTime}
WHERE NOT EXISTS (
    SELECT 1 FROM item i
    WHERE i.user_id = #{item.userId}
      AND i.consultant_id = #{item.consultantId}
      AND i.slot_id = #{item.slotId}
      AND i.manage_status = #{pendingCode}
      AND i.create_time > DATE_SUB(NOW(), INTERVAL #{dedupeSeconds} SECOND)
)

