SELECT IFNULL(SUM(quantity), 0)
FROM item
WHERE equipment_id = #{equipmentId}
  AND slot_date = #{date}
  AND manage_status IN (#{pendingCode}, #{approvedCode})
  AND start_time < #{endTime}
  AND end_time > #{startTime}

